      "keystrokes": "cat > main.cpp <<'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Circle { double r, x, y; };\nstatic double MAXR = 0.0; // global max radius for current test case\n\nstatic double distCir(const Circle &a, const Circle &b) {\n  double dx = a.x - b.x;\n  double dy = a.y - b.y;\n  double center = sqrt(dx*dx + dy*dy);\n  return center - (a.r + b.r);\n}\n\ndouble closestRec(vector<Circle> &a, int l, int r, vector<Circle> &tmp) {\n  if (r - l <= 3) {\n    double d = 1e100;\n    for (int i = l; i < r; ++i) {\n      for (int j = i+1; j < r; ++j) {\n        double val = distCir(a[i], a[j]);\n        if (val < d) d = val;\n      }\n    }\n    sort(a.begin()+l, a.begin()+r, [](const Circle &p, const Circle &q){ return p.y < q.y; });\n    return d;\n  }\n  int mid = (l + r) / 2;\n  double midx = a[mid].x;\n  double d = min(closestRec(a, l, mid, tmp), closestRec(a, mid, r, tmp));\n  // Merge by y\n  vector<Circle> merged;\n  merged.resize(r - l);\n  int p = l, q = mid, t = 0;\n  while (p < mid && q < r) {\n    if (a[p].y < a[q].y) merged[t++] = a[p++]; else merged[t++] = a[q++];\n  }\n  while (p < mid) merged[t++] = a[p++];\n  while (q < r) merged[t++] = a[q++];\n  for (int s = 0; s < t; ++s) a[l+s] = merged[s];\n  // Build strip\n  vector<Circle> strip; strip.reserve(r - l);\n  double limit = d + 2.0 * MAXR;\n  for (int idx = l; idx < r; ++idx) {\n    if (fabs(a[idx].x - midx) <= limit) strip.push_back(a[idx]);\n  }\n  // Check cross pairs in strip\n  for (size_t s = 0; s < strip.size(); ++s) {\n    for (size_t t2 = s+1; t2 < strip.size(); ++t2) {\n      double dy = strip[t2].y - strip[s].y;\n      if (dy > limit) break;\n      double cand = distCir(strip[s], strip[t2]);\n      if (cand < d) {\n        d = cand;\n        limit = d + 2.0 * MAXR; // update limit as d improves\n      }\n    }\n  }\n  return d;\n}\n\ndouble closest(vector<Circle> &points) {\n  if (points.size() < 2) return 0.0;\n  sort(points.begin(), points.end(), [](const Circle &a, const Circle &b){\n    if (a.x == b.x) return a.y < b.y; return a.x < b.x; });\n  vector<Circle> tmp(points.size());\n  return closestRec(points, 0, (int)points.size(), tmp);\n}\n\nint main() {\n  ios::sync_with_stdio(false);\n  cin.tie(nullptr);\n  int N;\n  cout.setf(std::ios::fixed); cout<<setprecision(6);\n  while (true) {\n    if(!(cin>>N)) return 0;\n    if (N == 0) break;\n    vector<Circle> pts; pts.reserve(N);\n    double maxR = 0.0;\n    for (int i = 0; i < N; ++i) {\n      double r, x, y; cin >> r >> x >> y;\n      pts.push_back({r, x, y});\n      if (r > maxR) maxR = r;\n    }\n    MAXR = maxR;\n    double ans = closest(pts);\n    if (ans < 0) ans = 0; // numerical safety\n    cout << ans << \"\\n\";\n  }\n  return 0;\n}\nCPP\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n",
