    if (ql <= l && r <= qr) {\n            return {st[p].minE, st[p].minO};\n        }\n        push(p);\n        int m = (l + r) >> 1;\n        auto left = query(p<<1, l, m, ql, qr);\n        auto right = query(p<<1|1, m+1, r, ql, qr);\n        return { min(left.first, right.first), min(left.second, right.second) };\n    }\n};\n\nint N, M, K;\nvector<int> X, Y;\n\nbool feasible(int t) {\n    int r = t - 1; // radius in original grid\n    int Umax = N + M - 2;      // u in [0, Umax]\n    int VminGlobal = -(M - 1); // v in [VminGlobal, VmaxGlobal]\n    int VmaxGlobal = (N - 1);\n    int Vsize = VmaxGlobal - VminGlobal + 1;\n    vector<vector<pair<int,int>>> add(Umax + 2), rem(Umax + 2);\n    for (int i = 0; i < K; ++i) {\n        int ui = X[i] + Y[i];\n        int vi = X[i] - Y[i];\n        int start = max(0, ui - r);\n        int end = min(Umax, ui + r);\n        if (start > end) continue;\n        int L = max(VminGlobal, vi - r);\n        int R = min(VmaxGlobal, vi + r);\n        if (L > R) continue;\n        int Lidx = L - VminGlobal;\n        int Ridx = R - VminGlobal;\n        add[start].push_back({Lidx, Ridx});\n        rem[end + 1].push_back({Lidx, Ridx});\n    }\n    SegTree seg; seg.init(Vsize, VminGlobal);\n    for (int u = 0; u <= Umax; ++u) {\n        for (auto &p : rem[u]) seg.update(1, 0, Vsize - 1, p.first, p.second, -1);\n        for (auto &p : add[u]) seg.update(1, 0, Vsize - 1, p.first, p.second, +1);\n        int LB = max(-u, u - 2*(M - 1));\n        int UB = min(u, 2*(N - 1) - u);\n        if (LB > UB) continue;\n        int Lidx = LB - VminGlobal;\n        int Ridx = UB - VminGlobal;\n        if (Lidx < 0) Lidx = 0;\n        if (Ridx > Vsize - 1) Ridx = Vsize - 1;\n        if (Lidx > Ridx) continue;\n        auto res = seg.query(1, 0, Vsize - 1, Lidx, Ridx);\n        int parity = u & 1;\n        int minVal = parity ? res.second : res.first;\n        if (minVal == 0) return true;\n    }\n    return false;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    if (!(cin >> N >> M >> K)) return 0;\n    X.resize(K); Y.resize(K);\n    for (int i = 0; i < K; ++i) cin >> X[i] >> Y[i];\n\n    int maxDist = (N - 1) + (M - 1);\n    int lo = 0, hi = maxDist;\n    while (lo < hi) {\n        int mid = (lo + hi + 1) / 2;\n        if (feasible(mid)) lo = mid; else hi = mid - 1;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}\nEOF\n",
