e dx = pts[j].x - pts[i].x;\n            double dy = pts[j].y - pts[i].y;\n            double L = sqrt(dx*dx + dy*dy);\n            double nx = -dy; // inward normal x\n            double ny = dx;  // inward normal y\n            double si = nx*pts[i].x + ny*pts[i].y;\n            double maxs = -1e100;\n            for(int t=0;t<n;t++){\n                double st = nx*pts[t].x + ny*pts[t].y;\n                if(st > maxs) maxs = st;\n            }\n            double Mi = (maxs - si) / L;\n            if(Mi < d_upper) d_upper = Mi;\n            edges[i] = {dx, dy, L, si};\n        }\n        if(d_upper < 0) d_upper = 0;\n\n        auto feasible = [&](double d)->bool{\n            const double BIG = 1e9;\n            vector<P> poly = { { -BIG, -BIG }, { BIG, -BIG }, { BIG, BIG }, { -BIG, BIG } };\n            for(int i=0;i<n && !poly.empty(); ++i){\n                double dx = edges[i].dx;\n                double dy = edges[i].dy;\n                double L = edges[i].L;\n                // inward normal n = (-dy, dx)\n                double a = -dy;\n                double b = dx;\n                double c = edges[i].s + d * L; // n·p_i + d*|e|\n                clipHalfPlane(poly, a, b, c);\n            }\n            return !poly.empty();\n        };\n\n        double lo = 0.0, hi = d_upper;\n        for(int it=0; it<60; ++it){\n            double mid = (lo+hi)/2.0;\n            if(feasible(mid)) lo = mid; else hi = mid;\n        }\n        cout << lo << \"\\n\";\n    }\n    return 0;\n}\nCPP\n\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n./main << 'EOF'\n4\n0 0\n10000 0\n10000 10000\n0 10000\n3\n0 0\n10000 0\n7000 1000\n6\n0 40\n100 20\n250 40\n250 70\n100 90\n0 70\n3\n0 0\n10000 10000\n5000 5001\n0\nEOF",
